+/// Whether `marker` occurs in `before` outside a double-quoted string.
+fn marker_outside_strings(before: &str, marker: &str) -> bool {
+    let mut in_string = false;
+    let mut escaped = false;
+    for (i, c) in before.char_indices() {
+        if in_string {
+            if escaped {
+                escaped = false;
+            } else if c == '\\' {
+                escaped = true;
+            } else if c == '"' {
+                in_string = false;
+            }
+        } else if c == '"' {
+            in_string = true;
+        } else if before[i..].starts_with(marker) {
+            return true;
+        }
+    }
+    false
